// static
bool StructTraits<::remoting::mojom::TransportRoute::DataView, ::remoting::mojom::TransportRoutePtr>::Read(
    ::remoting::mojom::TransportRoute::DataView input,
    ::remoting::mojom::TransportRoutePtr* output) {
  bool success = true;
  ::remoting::mojom::TransportRoutePtr result(::remoting::mojom::TransportRoute::New());
  
      if (success && !input.ReadType(&result->type))
        success = false;
      if (success && !input.ReadRemoteAddress(&result->remote_address))
        success = false;
      if (success && !input.ReadLocalAddress(&result->local_address))
        success = false;
  *output = std::move(result);
  return success;
}

